24	    async createInternalAccount(
25	        site?: Site | null,
26	        host = faker.internet.domainName(),
27	    ): Promise<[Account, Site, number]> {
28	        let _site: Site;
29	        let _account: Account;
30	
31	        if (!site) {
32	            _site = await this.siteService.initialiseSiteForHost(host);
33	            _account = await this.accountService.getAccountForSite(_site);
34	        } else {
35	            _site = site;
36	
37	            const { ap_id: accountApId } =
38	                await this.accountService.createInternalAccount(_site, {
39	                    username: faker.internet.username().replace('.', '_'),
40	                    name: faker.person.fullName(),
41	                    bio: null,
42	                    avatar_url: null,
43	                });
44	
45	            const accountByApId = await this.accountRepository.getByApId(
46	                new URL(accountApId),
47	            );
48	
49	            if (!accountByApId) {
50	                throw new Error(
51	                    `Account not found with ap_id ${accountApId} for site ${_site.id}`,
52	                );
53	            }
54	
55	            _account = accountByApId;
56	        }
57	
58	        const user = await this.db('users')
59	            .select('id')
60	            .where('account_id', _account.id)
61	            .first();
62	
