197	export function createFixtureManager(
198	    db: Knex,
199	    events: AsyncEvents = new AsyncEvents(),
200	) {
201	    const accountRepository = new KnexAccountRepository(db, events);
202	    const fedifyContextFactory = new FedifyContextFactory();
203	    const accountService = new AccountService(
204	        db,
205	        events,
206	        accountRepository,
207	        fedifyContextFactory,
208	        generateTestCryptoKeyPair,
209	    );
210	    const siteService = new SiteService(db, accountService, {
211	        getSiteSettings: async (host) => ({
212	            site: {
213	                description: faker.lorem.sentence(),
214	                title: faker.lorem.sentence(),
215	                icon: `https://${host}/avatar/${faker.string.uuid()}.jpg`,
216	            },
217	        }),
218	    });
219	    const postRepository = new KnexPostRepository(db, events);
220	
221	    return new FixtureManager(
222	        db,
